//! The operations behind every command. Each returns a serialisable report;
//! progress messages go through a [`Reporter`] so the CLI can print them in
//! order (and the JSON mode / server can collect them instead).

use std::path::PathBuf;

use serde::Serialize;
use sha2::{Digest, Sha256};

use crate::backend::{TartBackend, VmState};
use crate::config::{Config, SshSettings};
use crate::envfile::{self, EnvEntry, EnvLayers};
use crate::registry::Registry;
use crate::sshconfig::{self, HostBlock};
use crate::{Error, Result, ENV_DEST, SHARE_MOUNT};

/// Name used in generated files ("Generated by <tool> provision").
pub const TOOL_NAME: &str = "tctl";

pub trait Reporter {
    fn info(&mut self, msg: &str);
    fn warn(&mut self, msg: &str);
    fn dim(&mut self, msg: &str);
}

/// Collects messages instead of printing them (JSON mode, server, tests).
#[derive(Debug, Default, Serialize)]
pub struct Collected {
    pub messages: Vec<(String, String)>,
}
impl Reporter for Collected {
    fn info(&mut self, m: &str) {
        self.messages.push(("info".into(), m.into()));
    }
    fn warn(&mut self, m: &str) {
        self.messages.push(("warn".into(), m.into()));
    }
    fn dim(&mut self, m: &str) {
        self.messages.push(("dim".into(), m.into()));
    }
}

pub struct Ctx<'a> {
    pub cfg: &'a Config,
    pub backend: &'a dyn TartBackend,
    pub registry: Option<&'a Registry>,
    pub reporter: &'a mut dyn Reporter,
}

impl Ctx<'_> {
    fn vm_state(&self) -> Result<Option<VmState>> {
        Ok(self.backend.state_of(&self.cfg.vm_name)?.map(|v| v.state))
    }

    /// `Some(ip)` iff the VM is running and reports an IP.
    fn running_ip(&self) -> Result<Option<String>> {
        if self.vm_state()? != Some(VmState::Running) {
            return Ok(None);
        }
        self.backend.ip(&self.cfg.vm_name)
    }

    fn require_running(&self) -> Result<String> {
        self.running_ip()?
            .ok_or_else(|| Error::VmNotRunning(self.cfg.vm_name.clone()))
    }

    fn registry_do(&self, f: impl FnOnce(&Registry) -> Result<()>) {
        if let Some(reg) = self.registry {
            if let Err(e) = f(reg) {
                tracing::warn!("registry update failed: {e}");
            }
        }
    }
}

// ─── status / ip ─────────────────────────────────────────────────────────────

#[derive(Debug, Serialize)]
pub struct StatusReport {
    pub vm: String,
    /// "running" | "stopped" | "unknown" | Tart's raw state
    pub state: String,
    pub ip: Option<String>,
    pub share_dir: Option<PathBuf>,
    pub global_config: PathBuf,
    pub project_config: PathBuf,
}

pub fn status(ctx: &mut Ctx) -> Result<StatusReport> {
    let info = ctx.backend.state_of(&ctx.cfg.vm_name)?;
    let (state, ip) = match info {
        None => ("unknown".to_string(), None),
        Some(v) if v.state == VmState::Running => {
            ("running".to_string(), ctx.backend.ip(&ctx.cfg.vm_name)?)
        }
        Some(v) => (v.state_raw, None),
    };
    if let Some(ip) = &ip {
        let name = ctx.cfg.vm_name.clone();
        let ip = ip.clone();
        ctx.registry_do(|r| r.record_ip(&name, &ip));
    }
    Ok(StatusReport {
        vm: ctx.cfg.vm_name.clone(),
        state,
        ip,
        share_dir: ctx.cfg.share_dir.clone(),
        global_config: ctx.cfg.global_path.clone(),
        project_config: ctx.cfg.project_path.clone(),
    })
}

#[derive(Debug, Serialize)]
pub struct IpReport {
    pub vm: String,
    pub ip: String,
}

pub fn ip(ctx: &mut Ctx) -> Result<IpReport> {
    let ip = ctx.require_running()?;
    Ok(IpReport {
        vm: ctx.cfg.vm_name.clone(),
        ip,
    })
}

// ─── start / stop ────────────────────────────────────────────────────────────

#[derive(Debug, Serialize)]
pub struct StartReport {
    pub vm: String,
    pub already_running: bool,
    pub pid: Option<u32>,
    pub ip: Option<String>,
    pub log: Option<PathBuf>,
    pub share_dir: Option<PathBuf>,
}

/// Starts the VM detached and waits up to `wait_secs` for an IP (0 = don't wait).
pub fn start(ctx: &mut Ctx, wait_secs: u64) -> Result<StartReport> {
    let vm = ctx.cfg.vm_name.clone();
    ctx.registry_do(|r| r.upsert_config(ctx.cfg));
    if ctx.vm_state()? == Some(VmState::Running) {
        let ip = wait_for_ip(ctx, wait_secs)?;
        if let Some(ip) = &ip {
            ctx.registry_do(|r| r.record_ip(&vm, ip));
        }
        ctx.reporter.warn(&format!(
            "VM '{vm}' is already running ({}).",
            ip.as_deref().unwrap_or("IP unknown")
        ));
        return Ok(StartReport {
            vm,
            already_running: true,
            pid: None,
            ip,
            log: None,
            share_dir: ctx.cfg.share_dir.clone(),
        });
    }

    ctx.reporter.info(&format!("Starting VM '{vm}' …"));
    if let Some(dir) = &ctx.cfg.share_dir {
        ctx.reporter
            .dim(&format!("  share: {} → {SHARE_MOUNT}", dir.display()));
    }
    let log = ctx.cfg.log_path();
    let pid = ctx
        .backend
        .run_detached(&vm, ctx.cfg.share_dir.as_deref(), &log)?;

    // Persist immediately: a timeout leaves a live VM and its log to inspect.
    ctx.registry_do(|r| r.record_start(&vm, pid, &log, None));
    let ip = if wait_secs == 0 {
        None
    } else {
        wait_for_ip(ctx, wait_secs)?
    };
    match &ip {
        Some(ip) => ctx.reporter.info(&format!(
            "VM '{vm}' started (background PID {pid}, IP {ip})."
        )),
        None => ctx
            .reporter
            .info(&format!("VM '{vm}' started (background PID {pid}).")),
    }
    if let Some(ip) = &ip {
        let (vm, ip) = (vm.clone(), ip.clone());
        ctx.registry_do(|r| r.record_ip(&vm, &ip));
    }
    Ok(StartReport {
        vm,
        already_running: false,
        pid: Some(pid),
        ip,
        log: Some(log),
        share_dir: ctx.cfg.share_dir.clone(),
    })
}

fn wait_for_ip(ctx: &Ctx, wait_secs: u64) -> Result<Option<String>> {
    let started = std::time::Instant::now();
    loop {
        if let Some(ip) = ctx.backend.ip(&ctx.cfg.vm_name)? {
            return Ok(Some(ip));
        }
        if wait_secs == 0 {
            return Ok(None);
        }
        if started.elapsed() >= std::time::Duration::from_secs(wait_secs) {
            return Err(Error::StartTimeout(ctx.cfg.vm_name.clone(), wait_secs));
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
    }
}

#[derive(Debug, Serialize)]
pub struct StopReport {
    pub vm: String,
    pub was_running: bool,
}

pub fn stop(ctx: &mut Ctx) -> Result<StopReport> {
    let vm = ctx.cfg.vm_name.clone();
    if ctx.vm_state()? == Some(VmState::Running) {
        ctx.reporter.info(&format!("Stopping VM '{vm}' …"));
        ctx.backend.stop(&vm)?;
        ctx.reporter.info(&format!("VM '{vm}' stopped."));
        ctx.registry_do(|r| r.record_stop(&vm));
        Ok(StopReport {
            vm,
            was_running: true,
        })
    } else {
        ctx.reporter.warn(&format!("VM '{vm}' is not running."));
        Ok(StopReport {
            vm,
            was_running: false,
        })
    }
}

// ─── ssh config ──────────────────────────────────────────────────────────────

#[derive(Debug, Serialize)]
pub struct SshConfigReport {
    pub vm: String,
    pub ip: String,
    pub file: PathBuf,
    pub created: bool,
}

pub fn update_ssh_config(ctx: &mut Ctx) -> Result<SshConfigReport> {
    let ssh = ctx.cfg.ssh()?;
    let ip = ctx.require_running()?;
    write_ssh_config(ctx, &ssh, &ip)
}

fn write_ssh_config(ctx: &mut Ctx, ssh: &SshSettings, ip: &str) -> Result<SshConfigReport> {
    let vm = ctx.cfg.vm_name.clone();
    ctx.reporter.info(&format!("Resolved '{vm}' → {ip}"));
    let block = HostBlock {
        host: &vm,
        ip,
        user: &ssh.user,
        identity_file: &ssh.identity_file,
        remote_forward: &ctx.cfg.remote_forward,
        local_forward: &ctx.cfg.local_forward,
    };
    let existed = sshconfig::upsert_file(&ssh.config, &block)?;
    if existed {
        ctx.reporter
            .info(&format!("Updated existing '{vm}' entry → {ip}"));
    } else {
        ctx.reporter.info(&format!("Added new '{vm}' entry → {ip}"));
    }
    ctx.registry_do(|r| r.record_ip(&vm, ip));
    Ok(SshConfigReport {
        vm,
        ip: ip.to_string(),
        file: ssh.config.clone(),
        created: !existed,
    })
}

/// Makes sure the Host block exists with the current IP and user.
fn ensure_ssh_config_current(ctx: &mut Ctx, ssh: &SshSettings, ip: &str) -> Result<()> {
    let text = std::fs::read_to_string(&ssh.config).unwrap_or_default();
    let fresh = sshconfig::has_block(&text, &ctx.cfg.vm_name) && {
        let (host, user) = sshconfig::current_values(&text, &ctx.cfg.vm_name);
        host.as_deref() == Some(ip) && user.as_deref() == Some(ssh.user.as_str())
    };
    if !fresh {
        ctx.reporter.info(&format!(
            "Refreshing SSH config entry for '{}' …",
            ctx.cfg.vm_name
        ));
        write_ssh_config(ctx, ssh, ip)?;
    }
    Ok(())
}

/// Everything the CLI needs to `exec` ssh: settings and the (now current) host alias.
pub struct SshTarget {
    pub settings: SshSettings,
    pub host: String,
    pub ip: String,
}

pub fn prepare_ssh(ctx: &mut Ctx) -> Result<SshTarget> {
    let ssh = ctx.cfg.ssh()?;
    let ip = ctx.require_running()?;
    ensure_ssh_config_current(ctx, &ssh, &ip)?;
    ctx.reporter
        .info(&format!("Connecting to '{}' ({ip}) …", ctx.cfg.vm_name));
    Ok(SshTarget {
        settings: ssh,
        host: ctx.cfg.vm_name.clone(),
        ip,
    })
}

// ─── env / provision ─────────────────────────────────────────────────────────

fn load_layers(ctx: &mut Ctx) -> Result<EnvLayers> {
    let layers = EnvLayers::load(ctx.cfg)?;
    for s in &layers.skipped {
        ctx.reporter
            .dim(&format!("  - {} (not readable, skipped)", s.display()));
    }
    if layers.files.is_empty() {
        ctx.reporter.warn(&format!(
            "No readable env files (provision.env_files={:?}, resolved against {}).",
            layers.configured,
            ctx.cfg.project_dir.display()
        ));
    }
    for k in &layers.invalid_keys {
        ctx.reporter.warn(&format!("Skipping invalid key: {k}"));
    }
    Ok(layers)
}

pub fn content_hash(text: &str) -> String {
    hex::encode(Sha256::digest(text.as_bytes()))
}

#[derive(Debug, Serialize)]
pub struct ProvisionReport {
    pub vm: String,
    pub dest: String,
    pub layers: Vec<PathBuf>,
    pub skipped: Vec<PathBuf>,
    pub hash: String,
}

pub fn provision(ctx: &mut Ctx) -> Result<ProvisionReport> {
    let ssh = ctx.cfg.ssh()?;
    let ip = ctx.require_running()?;
    ensure_ssh_config_current(ctx, &ssh, &ip)?;
    let layers = load_layers(ctx)?;
    let rendered = layers.render(TOOL_NAME);

    let vm = ctx.cfg.vm_name.clone();
    ctx.reporter.info(&format!(
        "Pushing {} env layer(s) → {}@{vm}:{ENV_DEST}",
        layers.files.len(),
        ssh.user
    ));
    for f in &layers.files {
        ctx.reporter.dim(&format!("  + {}", f.display()));
    }
    let cmd = format!("sudo tee '{ENV_DEST}' >/dev/null && sudo chmod 644 '{ENV_DEST}'");
    let out = ctx.backend.run_remote(&ssh, &vm, &cmd, Some(&rendered))?;
    if out.status != 0 {
        return Err(Error::Backend(format!(
            "remote write failed ({}): {}",
            out.status,
            out.stderr.trim()
        )));
    }
    ctx.reporter
        .info("Done. Open a new login shell in the VM to pick up the variables.");

    let hash = content_hash(&rendered);
    {
        let (vm, hash) = (vm.clone(), hash.clone());
        ctx.registry_do(|r| {
            r.upsert_config(ctx.cfg)?;
            r.record_provision(&vm, &hash)
        });
    }
    Ok(ProvisionReport {
        vm,
        dest: ENV_DEST.into(),
        layers: layers.files,
        skipped: layers.skipped,
        hash,
    })
}

#[derive(Debug, Serialize)]
pub struct EnvReport {
    pub vm: String,
    pub layers: Vec<PathBuf>,
    pub skipped: Vec<PathBuf>,
    /// Effective entries, shell-quoted like the generated file; secret values masked unless `show_secrets`.
    pub effective: Vec<EnvEntry>,
    pub masked: bool,
    /// Filled in by [`env_diff`].
    pub diff: Option<EnvDiff>,
    #[serde(skip)]
    rendered: String,
}

#[derive(Debug, Serialize)]
pub struct EnvDiff {
    pub up_to_date: bool,
    /// Unified diff (masked unless `show_secrets`), empty when up to date.
    pub text: String,
}

/// Reads the layers and computes the effective environment (no VM contact).
pub fn env(ctx: &mut Ctx, show_secrets: bool) -> Result<EnvReport> {
    let layers = load_layers(ctx)?;
    let rendered = layers.render(TOOL_NAME);
    let mut effective = layers.effective();
    for e in &mut effective {
        e.value = if !show_secrets && envfile::is_secret_key(&e.key) {
            envfile::MASK.to_string()
        } else {
            envfile::shell_quote(&e.value)
        };
    }
    Ok(EnvReport {
        vm: ctx.cfg.vm_name.clone(),
        layers: layers.files,
        skipped: layers.skipped,
        effective,
        masked: !show_secrets,
        diff: None,
        rendered,
    })
}

/// Compares the rendered payload with the VM's current file; stores the result
/// in `report.diff` and returns it.
pub fn env_diff<'a>(
    ctx: &mut Ctx,
    report: &'a mut EnvReport,
    show_secrets: bool,
) -> Result<&'a EnvDiff> {
    let ssh = ctx.cfg.ssh()?;
    let ip = ctx.require_running()?;
    ensure_ssh_config_current(ctx, &ssh, &ip)?;
    let out = ctx.backend.run_remote(
        &ssh,
        &ctx.cfg.vm_name,
        &format!("cat '{ENV_DEST}' 2>/dev/null || true"),
        None,
    )?;
    if out.status != 0 {
        return Err(Error::Backend(format!(
            "remote read failed ({}): {}",
            out.status,
            out.stderr.trim()
        )));
    }
    // Mirror `$(…)` + `printf '%s\n'`: strip trailing newlines, then exactly one.
    let remote = format!("{}\n", out.stdout.trim_end_matches('\n'));
    let local = format!("{}\n", report.rendered.trim_end_matches('\n'));
    let diff = report.diff.insert(if remote == local {
        EnvDiff {
            up_to_date: true,
            text: String::new(),
        }
    } else {
        let text = similar::TextDiff::configure()
            .algorithm(similar::Algorithm::Lcs)
            .diff_lines(&remote, &local)
            .unified_diff()
            .context_radius(3)
            .header(&format!("vm:{ENV_DEST}"), "local (rendered)")
            .to_string();
        let text = if show_secrets {
            text
        } else {
            envfile::mask_rendered(&text)
        };
        EnvDiff {
            up_to_date: false,
            text,
        }
    });
    Ok(diff)
}
